 document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>setStep(+b.dataset.step));document.querySelectorAll('[data-content]').forEach(b=>b.onclick=()=>{if(printActive()||S.content===b.dataset.content)return;S.content=b.dataset.content;if(S.content==='initials'){S.text='SM';S.layout='row';}else S.layout='auto';change();});document.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{if(printActive()||S.kind===b.dataset.kind)return;S.kind=b.dataset.kind;S.mode=S.kind==='stamp20'?'stamp':'relief';change();resetCamera();coachSay(S.kind==='stamp20'?'큰 도장! 20mm 판에 글자를 거꾸로 크게 새겨요. 찍으면 바르게 나와요.':'키캡 키링! 14mm 판을 키캡에 끼워 딸깍 누르는 키링이 돼요.',{replay:true});});document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{if(printActive())return;S.mode=b.dataset.mode;change();if(S.mode==='through')coachSay(S.content==='icon'?'뚫림! 그림 모양대로 판이 뚫려서 키캡 밑판 색이 보여요. 떨어지는 조각이 없게 바깥 모양만 뚫어요.':'뚫림 글자! ㅁ·ㅇ처럼 떨어질 가운데는 1.2mm 다리로 판에 이어서 스텐실처럼 만들어요.',{replay:true});if(S.mode==='puffy')coachSay('말랑 모드! 가장자리가 둥글게 부풀어 올라요. 포스카로 색칠하기 좋아요.',{replay:true});if(S.mode==='stamp')coachSay('도장 모드! 글자를 거꾸로 새겨서 찍으면 바르게 나와요. 키캡 테두리보다 1.5mm 높아요.',{replay:true});});
 const editText=e=>{if(printActive())return;if(S.content==='icon'){const t=cleanTag(e.target.value);if(e.target.value!==t)e.target.value=t;S.tag=t;}else S.text=e.target.value;change(true,{delay:100,group:'text'});};
 $('textIn').addEventListener('compositionstart',()=>{composing=true;syncHistory();});$('textIn').addEventListener('compositionend',e=>{composing=false;editText(e);});$('textIn').addEventListener('input',e=>{if(!e.isComposing&&!composing)editText(e);});$('textIn').addEventListener('blur',()=>activeHistory().breakGroup());$('heightIn').oninput=e=>{if(printActive())return;S.relief=+e.target.value;change(true,{delay:60,group:'height'});};$('heightIn').onchange=()=>activeHistory().breakGroup();
 for(const style of ['none',...Object.keys(EDGES)]){const b=document.createElement('button');b.type='button';b.dataset.edge=style;b.setAttribute('aria-label',EDGES[style]?.name||'테두리 없음');if(style==='none')b.textContent='없음';else b.append(edgeThumb(style));b.onclick=()=>{if(printActive())return;S.edge=style;change();if(style!=='none')coachSay(EDGES[style].name+' 테두리! 키캡 밑판 홈 벽에서 0.6mm 떨어져 있어서 끼울 때 걸리지 않아요. 테두리만 다른 색으로 칠해 봐요.',{replay:true});};$('edgeTiles').append(b);}
 for(const f of FONTS){const b=document.createElement('button');b.type='button';b.className='font-choice';b.dataset.font=f.id;b.setAttribute('aria-label',f.label+' 글씨');const c=document.createElement('canvas');c.width=160;c.height=112;c.className='work-thumb';c.setAttribute('aria-hidden','true');const label=document.createElement('span');label.textContent=f.label;b.append(c,label);b.onclick=()=>{if(printActive())return;S.font=f.id;change();};$('fontTiles').append(b);}
 for(const [color,label] of [['#ff7b92','딸기'],['#ffd45f','레몬'],['#65baff','하늘'],['#77cbb6','민트'],['#b7a0e9','포도'],['#f5f0e5','크림']]){const b=document.createElement('button');b.dataset.color=color;b.style.setProperty('--swatch',color);b.setAttribute('aria-label',label);b.title=label;b.onclick=()=>{if(printActive())return;S.color=color;recordDesignEdit();sync();if(current)showModel();try{localStorage.setItem('click-design-v2',JSON.stringify(S));}catch{}};$('colors').append(b);}
