 $('nextBtn').onclick=()=>{if(step===1&&!activeSlice()&&ready()){coachSay('먼저 오른쪽 ✦ 슬라이싱 버튼을 직접 눌러봐요! 그래야 프린터가 따라갈 길이 생겨요.',{replay:true});const b=$('sliceBtn');b.classList.remove('is-calling');void b.offsetWidth;b.classList.add('is-calling');if(!browserSliceBusy)b.focus();return;}step<2?setStep(step+1):openReset();};$('backBtn').onclick=()=>setStep(Math.max(0,step-1));$('restartBtn').onclick=()=>openReset();$('resetDialog').onclose=()=>{if($('resetDialog').returnValue==='reset')printActive()?holdPrint():reset();};$('heldJob').onclick=()=>heldActive()?toast('「'+heldJob.label+'」 · '+(stateLabel[heldJob.state]||heldJob.state)+(heldJob.state==='printing'?' '+(Number(heldJob.progress)||0)+'%':'')):dropHeld();document.querySelector('.brand').onclick=e=>{e.preventDefault();setStep(0);};
 $('topViewBtn').onclick=()=>resetCamera(true);document.querySelectorAll('[data-fit]').forEach(b=>b.onclick=()=>chooseFit(b.dataset.fit));document.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>choosePairSlot(+b.dataset.slot));document.querySelectorAll('[data-kit]').forEach(b=>b.onclick=()=>chooseKit(b.dataset.kit));$('resetViewBtn').onclick=()=>resetCamera();$('layerRange').oninput=()=>chooseLayer(Number($('layerRange').value));$('playBtn').onclick=()=>{if($('playBtn').textContent==='Ⅱ'){clearInterval(layerTimer);$('playBtn').textContent='▶';return;}$('playBtn').textContent='Ⅱ';layerSelection=1;$('layerRange').value=1;updateLayer();layerTimer=setInterval(()=>{const input=$('layerRange');if(+input.value>=+input.max){clearInterval(layerTimer);$('playBtn').textContent='▶';return;}layerSelection=+input.value+1;input.value=layerSelection;updateLayer();beep(400+Number(input.value)*25);},650);};
