 $('importBtn').onclick=()=>$('importFile').click();$('importFile').onchange=async e=>{const f=e.target.files[0];if(!f||printActive())return;try{if(f.size>10000)throw Error('작품 설정 JSON 파일을 선택해주세요.');const data=JSON.parse(await f.text());if(printActive())return;if(data.version!==2||!data.design)throw Error('이 공방에서 저장한 작품.json이 아닙니다.');Object.assign(S,restoreDesign(data.design));change();toast('저장했던 상상을 불러왔어요.');}catch(e){toast(e.message);}e.target.value='';};
